import graph;
size(280,220);
pen p = currentpen;
draw(scale(2)*unitcircle);
pair A = dir(90);
pair B = dir(210);
pair C = dir(330);
dot(A); dot(B); dot(C); dot((0,0));
draw(A--B); draw(A--C);
draw((0,0)--A, dashed); draw((0,0)--B, dashed);
label("$A$", A, N); label("$B$", B, SW); label("$C$", C, SE);
label("$O$", (0,0), SE);
label("$\\angle AOB$", (0.55,0.35), NE);
label("$\\angle ACB$", C, S);

import graph;
size(280,220);
pen p = currentpen;
draw(scale(2)*unitcircle);
pair T = dir(50);
pair P = 3.3*dir(50);
dot((0,0)); dot(T); dot(P);
draw(T--P);
draw((0,0)--T, dashed);
draw(T+dir(140)*0.42 -- T+dir(140)*0.42 + dir(50)*0.42 -- T+dir(50)*0.42);
label("$O$", (0,0), S);
label("$T$", T, NW);
label("$P$", P, E);
label("$r$", T/2, SW);
label("$PT$", (T+P)/2, NE);
label("$OP$", P/2, SE);

import graph;
size(300,230);
pen p = currentpen;
draw(scale(2)*unitcircle);
pair P = (3.4,0.6);
pair A = (1.412,1.419);
pair B = (0,2);
pair C = (1.951,0.439);
pair D = (-2,0);
pair T = (0.858,1.807);
dot(P); dot(A); dot(B); dot(C); dot(D); dot(T);
draw(P--A--B);
draw(P--C--D);
draw(P--T);
label("$P$", P, E);
label("$A$", A, NE); label("$B$", B, N);
label("$C$", C, SE); label("$D$", D, SW);
label("$T$", T, W);

import graph;
size(280,230);
pen p = currentpen;
draw(scale(2)*unitcircle);
pair A = (-1.833,0.8);
pair B = (1.833,0.8);
pair M = (0,0.8);
draw(A--B);
draw((0,0)--M--(0,2), dashed);
dot((0,0)); dot(A); dot(B); dot(M); dot((0,2));
label("$O$", (0,0), SW);
label("$A$", A, W); label("$B$", B, E);
label("$M$", M, NE);
label("$P$", (0,2), N);
